const fs = require('node:fs');
const path = require('node:path');
const root = path.resolve(__dirname, '..');
const dist = path.dirname(require.resolve('leaflet/dist/leaflet.js'));
const js = fs.readFileSync(path.join(dist, 'leaflet.js'), 'utf8').replace(/\/\/# sourceMappingURL=.*$/gm, '');
const css = fs.readFileSync(path.join(dist, 'leaflet.css'), 'utf8');
fs.writeFileSync(path.join(root, 'src/features/location/leafletBundle.ts'),
  '// Generated by scripts/build-leaflet-assets.cjs. Leaflet 1.9.4, BSD-2-Clause.\n' +
  '// Local JS/CSS avoids a CDN dependency; see assets/maps/Leaflet-LICENSE.txt.\n' +
  `export const leafletJavaScript = ${JSON.stringify(js)};\nexport const leafletCss = ${JSON.stringify(css)};\n`);
fs.mkdirSync(path.join(root, 'assets/maps'), { recursive: true });
fs.copyFileSync(path.join(dist, '../LICENSE'), path.join(root, 'assets/maps/Leaflet-LICENSE.txt'));
console.log('Bundled Leaflet JS/CSS and license locally.');
